class Solution:
    def isAnagram(self, s: str, t: str) -> bool:
        if len(s) != len(t):
            return False
        balance = {}
        for ch in s:
            balance[ch] = balance.get(ch, 0) + 1
        for ch in t:
            balance[ch] = balance.get(ch, 0) - 1
        return all(v == 0 for v in balance.values())
```

